type Any=Record<string,any>;
let access=sessionStorage.getItem('ops-token')||'';
async function api(path:string,method='GET',body?:unknown){
  const response=await fetch('/api'+path,{method,headers:{'Content-Type':'application/json',...(access?{Authorization:'Bearer '+access}:{})},...(body!==undefined?{body:JSON.stringify(body)}:{})});
  const data=await response.json();
  if(!response.ok) throw new Error(typeof data.detail==='string'?data.detail:JSON.stringify(data.detail));
  return data;
}
const pretty=(v:unknown)=>JSON.stringify(v,null,2);
const date=(v?:string)=>v?new Date(v).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit'}):'—';
const statusText:Any={queued:'排队中',running:'运行中',waiting_child:'等待子调用',success:'成功',failed:'失败',cancelled:'已取消',interrupted:'已中断',skipped:'已跳过',pending:'待审批',approved:'已上架',rejected:'已驳回'};
function Badge({status}:{status:string}){return <span className={'badge '+status}><i/>{statusText[status]||status}</span>}
function Empty({title,detail,action}:{title:string,detail?:string,action?:React.ReactNode}){return <div className="empty"><Layers3 size={32}/><h3>{title}</h3><p>{detail}</p>{action}</div>}
function JsonField({label,value,onChange,rows=5}:{label:string,value:string,onChange:(v:string)=>void,rows?:number}){return <label className="field">{label}<textarea className="mono" rows={rows} value={value} onChange={e=>onChange(e.target.value)}/></label>}
function Modal({title,children,close}:{title:string,children:React.ReactNode,close:()=>void}){return <div className="modal-shade" onClick={close}><section className="modal" role="dialog" aria-modal="true" aria-label={title} onClick={e=>e.stopPropagation()}><div className="row between"><h2>{title}</h2><button className="icon" aria-label="关闭" onClick={close}><X size={20}/></button></div>{children}</section></div>}
const template=(lang='python')=>({language:lang,interpreter:'',code:lang==='python'?'from ops_sdk import inputs, result\n\nparams = inputs()\nprint("开始执行", flush=True)\nresult({"ok": True, "message": params.get("message", "Hello, 运维助手")})\n':'#!/bin/sh\nset -eu\nprintf \'{"ok":true}\\n\'\n',parameters:[],variables:{},dependencies:[],args:[],timeout:300});
