 const [user,setUser]=useState<Any|null>(null),[loading,setLoading]=useState(!!access),[page,setPage]=useState('overview'),[resources,setResources]=useState<Any[]>([]),[runs,setRuns]=useState<Any[]>([]),[stats,setStats]=useState<Any>({runs:{}}),[health,setHealth]=useState<Any>({}),[selected,setSelected]=useState<Any|null>(null),[runId,setRunId]=useState(''),[toast,setToast]=useState(''),[create,setCreate]=useState(''),[query,setQuery]=useState('');
 const notify=useCallback((msg:string)=>{setToast(msg);setTimeout(()=>setToast(''),6000)},[]);
 const refresh=useCallback(async()=>{try{const [r,ru,s,h]=await Promise.all([api('/resources'),api('/runs'),api('/stats'),api('/health')]);setResources(r);setRuns(ru);setStats(s);setHealth(h)}catch(e){notify(String(e))}},[notify]);
 useEffect(()=>{if(access)api('/auth/me').then(setUser).catch(()=>{access='';sessionStorage.removeItem('ops-token')}).finally(()=>setLoading(false))},[]);
