 const removeResource=async(r:Any)=>{const label=r.kind==='app'?'应用':'脚本';if(!confirm(`确定删除${label}“${r.name}”？\n\n删除后将从${r.kind==='app'?'应用编排':'脚本库'}中移除，并停用其定时任务；历史运行、已发布版本和审计记录仍会保留。`))return;await act(()=>api('/resources/'+r.id,'DELETE'),label+'已删除')};
 const inspect=(id:string)=>{setRunId(id);setPage('runs')};
 const navigation=[['overview','工作台',LayoutDashboard],['scripts','脚本库',Code2],['apps','应用编排',GitBranch],['runs','运行记录',Activity],['schedules','定时任务',Clock3],['market','能力市场',Box],['ai','AI 助理',Sparkles],...(user?.role==='admin'?[['initialize','AI 初始化',FolderSearch]]:[]),['audit','审计日志',ShieldCheck],...(user?.role==='admin'?[['users','用户管理',Users],['settings','系统设置',Settings2]]:[])];
