   if(!baseUrl||!hasKey){setModels([]);setLoadingModels(false);setModelError(false);setModelStatus(!baseUrl?'填写服务地址和 API Key 后将自动获取模型列表。':'填写 API Key 后将自动获取模型列表。');return}
